def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    lowest = min(v1, v2, v3)

    return {
        "value": lowest,
        "trace": {
            "v1_2018": v1,
            "v2_2017": v2,
            "v3_2016": v3,
            "lowest_alternative_investments": lowest,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
